import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine());
        try (PrintWriter w = new PrintWriter(new FileWriter("jual.txt"))) {
            for (int i = 0; i < n; i++) {
                w.println(in.nextLine());
            }
        }
        String terlaris = "";
        int maks = -1;
        try (BufferedReader r = new BufferedReader(new FileReader("jual.txt"))) {
            String baris;
            while ((baris = r.readLine()) != null) {
                String[] b = baris.split(" ");
                int jumlah = Integer.parseInt(b[1]);
                if (jumlah > maks) {
                    maks = jumlah;
                    terlaris = b[0];
                }
            }
        }
        System.out.println("Terlaris: " + terlaris + " (" + maks + ")");
    }
}
